def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # A vertical guide is a column containing a colored marker below the bands.
    guides = set()
    marker_starts = {}
    for c in range(w):
        r = h - 1
        while r >= 0 and grid[r][c] != 0 and grid[r][c] == grid[h-1][c]:
            r -= 1
        has_gap = any(
            0 < c < w - 1 and grid[rr][c] == 0 and grid[rr][c-1] != 0 and grid[rr][c-1] == grid[rr][c+1]
            for rr in range(h)
        )
        if h - 1 - r >= 2 or (grid[h-1][c] != 0 and has_gap):
            guides.add(c)
            marker_starts[c] = r + 1
    events = {c: [] for c in guides}
    for r, row in enumerate(grid):
        for c in guides:
            if c > 0 and c + 1 < w and row[c] == 0 and row[c-1] != 0 and row[c-1] == row[c+1]:
                color = row[c-1]
                out[r][c] = color
                events[c].append((r, color))
    # Each horizontal band colors its guide upward to the preceding band.
    for c, evs in events.items():
        previous = -1
        for r, color in evs:
            for rr in range(previous + 1, r + 1):
                out[rr][c] = color
            previous = r
        if evs:
            marker_color = grid[h-1][c]
            for rr in range(evs[-1][0] + 1, h):
                out[rr][c] = marker_color
    return out
